    impure function seg_base(f : in string) return integer is
    begin
        if f = "rtl/roms/video2.mif" then
            return 0;
        end if;
        if f = "rtl/roms/keyboard.mif" then
            return 8192;
        end if;
        if f = "rtl/roms/apple2e.mif" then
            return 10240;
        end if;
        report "spram_const: unknown init_file: " & f severity failure;
        return 0;
    end function seg_base;

    constant base : integer := seg_base(init_file);
    signal mem : ram_type := ROM;
begin
    assert databits = 8 report "spram_const: only 8-bit data is supported" severity failure;
    process (clock)
    begin
        if (clock'event and clock = '1') then
            if wren = '1' then
                mem(base + to_integer(unsigned(address))) <= data;
                q <= data;
            else
                q <= mem(base + to_integer(unsigned(address)));
            end if;
        end if;
    end process;
end architecture arch;
